// streamAssertReadZeroOnError asserts Read returns zero alongside any error.
func streamAssertReadZeroOnError(
	tb testing.TB,
	s Stream,
	fx StreamFixture,
) {
	tb.Helper()
	ctx, cancel := context.WithCancel(tb.Context())
	cancel()
	got, err := s.Read(ctx, fx.Key())
	if err == nil {
		tb.Skip("Read answered for a cancelled context, so this check has no error to inspect")
	}

	var zero string
	if got != zero {
		tb.Errorf("Read must return the zero value alongside an error: got %+v, want %+v (err %v)",
			got, zero, err)
	}
}

