	for _, row := range rc.rows {
		rc.AddCheck(row.bind(fx))
	}
	rc.Fail(t, "ProveStream")
	s := streamSuite(fx).With(rc.Extra...).Without(rc.Drops...)
	doors := suite.Doors(rc.Subjects...)
	defects := streamProofs()
